import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int P = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] Parent = new int[P + 1];
        int[] Rank = new int[P + 1];
        for (int i = 1; i <= P; i++) {
            Parent[i] = i;
            Rank[i] = 1;
        }

        // find_parent function
        java.util.function.Function<Integer, Integer> find_parent = new java.util.function.Function<Integer, Integer>() {
            public Integer apply(Integer nd) {
                if (Parent[nd] != nd) {
                    Parent[nd] = apply(Parent[nd]);
                }
                return Parent[nd];
            }
        };

        // Union function
        java.util.function.BiConsumer<Integer, Integer> Union = (nd1, nd2) -> {
            int root1 = find_parent.apply(nd1);
            int root2 = find_parent.apply(nd2);
            if (root1 != root2) {
                if (Rank[root1] >= Rank[root2]) {
                    Parent[root2] = root1;
                    Rank[root1]++;
                } else {
                    Parent[root1] = root2;
                    Rank[root2]++;
                }
            }
        };

        for (int i = 1; i <= P; i++) {
            long valueLong = ((long) K * i) % P;
            int value = (int) valueLong;
            int Pa = find_parent.apply(i);
            int Pb = find_parent.apply(value);
            if (Pa != Pb) {
                Union.accept(Pa, Pb);
            }
        }

        Set<Integer> groups = new HashSet<>();
        for (int i = 1; i <= P; i++) {
            groups.add(find_parent.apply(i));
        }

        long MAXN = 1000000007L;

        // fast_exp_pow function
        java.util.function.BiFunction<Long, Long, Long> fast_exp_pow = (base, exp) -> {
            long res = 1;
            long b = base;
            long e = exp;
            while (e > 0) {
                if ((e & 1) == 1) {
                    res = (res * b) % MAXN;
                }
                b = (b * b) % MAXN;
                e >>= 1;
            }
            return res;
        };

        long ways;
        if (K == 0) {
            ways = fast_exp_pow.apply((long) P, (long) P - 1);
        } else if (K == 1) {
            ways = fast_exp_pow.apply((long) P, (long) P);
        } else {
            ways = fast_exp_pow.apply((long) P, (long) groups.size());
        }

        System.out.println(ways);
    }
}
